__NUXT_JSONP__("/sp/teachers", {data:[{details:{slug:"sp",pageTitle:"Clases y profesores de MLI | Mentor Language Institute",pageDescription:"En los cursos de inglés general, los estudiantes adquieren habilidades prácticas utilizando materiales del mundo real como publicaciones en Twitter, charlas TED y clips de películas.",title:"Clases y profesores de MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"Las clases se enfocan en Habilidades Prácticas",description:["En los cursos de inglés general, los estudiantes adquieren habilidades prácticas utilizando materiales del mundo real como publicaciones en Twitter, charlas TED y clips de películas. Usando estos materiales, los estudiantes sistemáticamente adquieren patrones de gramática, escritura, lectura, vocabulario, escuchar y hablar.","Además, TOEFL® y otros cursos de preparación para exámenes proporcionan estrategias para resolver problemas con sus propios métodos."]},{title:"Profesores de MLI",description:["1,200 estudiantes se gradúan de MLI cada año, lo que habla de la calidad de nuestros profesores. Nos esforzamos constantemente para mejorar las habilidades de los instructores a través de observaciones, evaluaciones y talleres de desarrollo profesional."],checklist:[{title:"Requisitos de contratación (lista de verificación para contratar docentes)",lists:["Graduado de cuatro años de la universidad","3 años de experiencia como instructor de Inglés","Calificaciones enseñanado como TESOL","Conocimiento de pruebas de examen como TOEFL® \u002F GMAT®","Fuertes habilidades de comunicación","Pasión y compromiso por enseñar"]},{title:"Selección de método",lists:["Curriculum y diploma","Examen de gramática ","Entrevista","Modelo de clase"],note:"La tasa de contratación es inferior al 20%."}]},{title:"Sistema de entrenamiento y evaluación",description:["En MLI, verificamos los siguientes tres elementos cada 12 semanas para mantener la calidad del docente."],listType:"decimal",lists:["Los estudiantes evalúan libros de texto e instructores. Los instructores con un índice de satisfacción de 85% o menos se someten a capacitación de desarrollo profesional.","Observación de la lección y comentarios proporcionados por el equipo superior académico","Desarrollo profesional y talleres de capacitación para mejorar la enseñanza."],note:"¡La administración y los instructores se esfuerzan por mejorar la calidad de la educación todos los días!"}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:31.177Z",updatedAt:"2025-05-26T12:06:27.932Z"}}],fetch:{},mutations:void 0});